library(shiny)
library(bslib)
library(ggplot2)
library(readr)
library(dplyr)

# ============================================================
# RLifeHistory Remote Console v4
# ------------------------------------------------------------
# - Keeps the v3.2 detached background NIMBLE runner.
# - Reads REAL output CSV files generated by the existing vignette.
# - Shows WAIC comparison, change-point probabilities, convergence,
#   posterior model curves, and the completed HTML report.
# - No change to the statistical model.
# ============================================================

possible_paths <- c(
  "data/AusData.csv", "../data/AusData.csv", "AusData.csv",
  "../AusData.csv", "AUS.csv", "../AUS.csv"
)
existing_paths <- possible_paths[file.exists(possible_paths)]
aus <- if (length(existing_paths)) {
  read_csv(existing_paths[1], show_col_types = FALSE)
} else {
  NULL
}

status_dir <- "run_status"
status_file <- file.path(status_dir, "latest.txt")
log_file <- file.path(status_dir, "latest.log")
report_file <- "AusData_simple_NIMBLE_slope_models.html"

comparison_file <- file.path("output", "model_comparison_WAIC.csv")
slope_file <- file.path("output", "slope_probabilities.csv")
rhat_file <- file.path("output", "convergence_Rhat.csv")
curves_file <- file.path("output", "posterior_model_curves.csv")
best_curve_png <- file.path("output", "best_model_posterior_curve.png")
slope_png <- file.path("output", "slope_toward_present.png")

read_status <- function() {
  if (!file.exists(status_file)) {
    return(list(status = "READY"))
  }

  z <- readLines(status_file, warn = FALSE)
  parts <- strsplit(z, "=", fixed = TRUE)
  keys <- vapply(parts, `[`, character(1), 1)
  vals <- vapply(
    parts,
    function(x) paste(x[-1], collapse = "="),
    character(1)
  )

  as.list(setNames(vals, keys))
}

safe_csv <- function(path) {
  if (!file.exists(path)) {
    return(NULL)
  }

  tryCatch(
    read.csv(path, stringsAsFactors = FALSE, check.names = FALSE),
    error = function(e) NULL
  )
}

fmt_num <- function(x, digits = 3) {
  if (length(x) == 0 || is.na(x) || !is.finite(x)) {
    return("—")
  }
  formatC(x, format = "f", digits = digits)
}

